let bytes = null;
function png() {
  if (bytes) return bytes;
  const bin = atob(LOGO_PNG_B64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  bytes = out;
  return out;
}

export function logoResponse(request) {
  if (request.method !== "GET" && request.method !== "HEAD")
    return new Response(null, { status: 405, headers: { allow: "GET, HEAD" } });
  if (request.headers.get("if-none-match") === LOGO_PNG_ETAG)
    return new Response(null, { status: 304, headers: { etag: LOGO_PNG_ETAG } });
  const body = request.method === "HEAD" ? null : png();
  return new Response(body, {
    status: 200,
    headers: {
      "content-type": "image/png",
      "content-length": String(png().length),
      "cache-control": "public, max-age=86400",
      etag: LOGO_PNG_ETAG,
      "access-control-allow-origin": "*",
      "x-content-type-options": "nosniff",
    },
  });
}
